pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(amount < type(uint256).max);
        vm.assume(receiver != address(c));
        vm.deal(address(c), amount + 1);
        uint before = receiver.balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        assertEq(receiver.balance - before, amount, "receiver must receive exactly amount");
    }
}
